def sumOfNumberAndReverse(num: int) -> bool:
    # Helper to reverse an integer (preserving leading zeros in calculation)
    def reverse(k: int) -> int:
        rev = 0
        while k > 0:
            rev = rev * 10 + k % 10
            k //= 10
        return rev

    # Try all k from 0 up to num
    for k in range(num + 1):
        if k + reverse(k) == num:
            return True
    return False
